     The prior builds still allowed the live DEM/vector/contour pipeline to leave the UI
     spinning in some browsers. This path deliberately completes a preliminary screening
     analysis from the current property grid first, then reports clearly that the output is
     screening-grade. It does not fetch live terrain/vector data during the button action. */
  if(earthlineAnalysisIsBusy15686()&&!options.queued){
    earthlineNotice("Site analysis is already running…");
    return false;
  }
  const runId=++EARTHLINE_ACTIVE_ANALYSIS_15685;
  const myStartGen=++M.searchGen;
  earthlineSetAnalysisBusy15685(true);
  try{
    const searchInput=document.getElementById("searchInput");
    const enteredText=searchInput?searchInput.value:"";
    const enteredKey=earthlineSearchKey(enteredText);
    if(enteredKey&&enteredKey!==M.appliedSearchText){
      earthlineNotice("First moving to the searched site…");
      const ok=await runSearch({autoAnalyze:false});
      if(!ok){earthlineReady("Search did not resolve. Try a clearer address or click a site on the map.");return false;}
    }

    // In regional/city mode, create a small selectable analysis area from the current map center.
    if(earthlineLargeAreaMode()||earthlinePlanningMode()){
      const p=earthlineCurrentAnalysisPoint(),parent=M.loc||{};
      const selected=earthlineSelectedSiteFromCenter(parent,p.lng,p.lat,20);
      const runGen=++M.searchGen;
      earthlineProgress("terrain","preparing a 20-acre analysis area…");
      await earthlineEaseToAnalysisPoint(p.lng,p.lat,17).catch(()=>{});
      const ok=await applyLocation(selected,null,runGen,{analyzeNow:false,preserveMapView:true});
      if(!ok){earthlineReady("Could not prepare the selected analysis area.");return false;}
    }

    // Keep the analysis centered on the live map position at property zoom.
    if(earthlineMapActive()&&earthlineMap.getCenter){
      const c=earthlineMap.getCenter();
      if(c&&Number.isFinite(c.lng)&&Number.isFinite(c.lat)){M.centerLng=c.lng;M.centerLat=c.lat;}
      if(earthlineMap.getZoom)M.viewZoom=Math.max(16.5,Math.min(17,earthlineMap.getZoom()||17));
    }else M.viewZoom=Math.max(16.5,Math.min(17,M.viewZoom||17));
    M.cellM=5*mppAt(Math.min(M.viewZoom,17),M.centerLat);

    if(!earthlineApplyAnalysisBoundary()){
      earthlineReady("Select or draw an analysis area before running property analysis.");
      return false;
    }

    earthlineProgress("terrain","building fast preliminary terrain…");
    await earthlineYield();
    M.seed=hashStr(((M.loc&&M.loc.name)||"selected site")+"|"+M.zone+"|fast-screening-15690");
    M.realMode=false;
    M.demSource="fast preliminary terrain screen";
    buildTerrainProceduralWrap();
    buildBoundary();
    M.minH=Infinity;M.maxH=-Infinity;
    for(let i=0;i<N;i++){if(M.h[i]<M.minH)M.minH=M.h[i];if(M.h[i]>M.maxH)M.maxH=M.h[i];}
    M.terrainReady=true;M.previewReady=true;M.demReady=true;M.analysisReady=false;M.terrainStamp=earthlineTerrainStamp();

    earthlineProgress("hydrology","running fast water-flow model…");
    await pitFill(myStartGen);if(earthlineIsStale(myStartGen)){earthlineReady("Analysis was cancelled by a newer request.");return false;}
    await flowRoute(myStartGen);if(earthlineIsStale(myStartGen)){earthlineReady("Analysis was cancelled by a newer request.");return false;}
    await computeRecharge(myStartGen);if(earthlineIsStale(myStartGen)){earthlineReady("Analysis was cancelled by a newer request.");return false;}

    runC:Number(parent&&parent.runC||0.35),zones:["Selected Area"]
  };
}
function earthlineCurrentAnalysisCenter(){
  if(earthlineMapActive()&&earthlineMap.getCenter){
    const c=earthlineMap.getCenter();
    if(c&&Number.isFinite(c.lng)&&Number.isFinite(c.lat))return [c.lng,c.lat];
  }
  return [Number(M.centerLng||M.loc&&M.loc.lng||0),Number(M.centerLat||M.loc&&M.loc.lat||0)];
}
function earthlinePreparePlanningAquiferView(loc=M.loc){
  if(!loc||!M.layers||!M.layers.usgsAquifer)return;
  const planningView=earthlinePlanningMode(loc)||earthlineLocIsLargeArea(loc);
  if(!planningView)return;
  // Official aquifer context is a regional/city feature and must not be disabled merely
  // because the searched geography is large. Parcel recharge remains analysis-only.
  M.layers.usgsAquifer.on=true;
  setTimeout(()=>{
    if(M.loc!==loc)return;
    if(MB_ON())fetchUSGSAquifers();
    render();
  },80);
}
async function runSearch(options={}){
  const autoAnalyze=!!(options&&options.autoAnalyze===true);
  const input=document.getElementById("searchInput");
  let q=input?input.value:"";
  const blankRequest=!q.trim();
  // The primary action must always do useful work. With a blank field, use the
  // current/default Earthline location directly and skip an unnecessary geocoder call.
  let loc=null;
  if(blankRequest){
    loc=M.loc||GAZ[0];
    q=loc.fullName||((loc.name||"")+(loc.sub?", "+loc.sub:""));
    if(input)input.value=q;
  }
  const myGen=++M.searchGen;
  M.terrainReady=false;M.analysisReady=false;
  earthlineProgress("geocode");
  if(!loc)loc=earthlineRegionOverride(q);
  if(MB_ON()&&!loc){
    try{loc=await earthlineTimed("geocoding",()=>geocodeMapbox(q,myGen));}catch(e){loc=null;}
  }
  if(earthlineIsStale(myGen))return false;
  if(!loc)loc=findLoc(q);
  if(!loc){earthlineReady(MB_ON()?"No result — try a fuller address.":"Offline mode: choose a suggested site.");return false;}

  const originalLoc=loc;
  const planningRequest=autoAnalyze&&(earthlinePlanningMode(loc)||earthlineLocIsLargeArea(loc));
  const ok=await applyLocation(loc,null,myGen,{analyzeNow:autoAnalyze&&!planningRequest});
  if(!ok||earthlineIsStale(myGen))return false;
  earthlinePreparePlanningAquiferView(loc);
  M.appliedSearchText=earthlineSearchKey(q);
  addRecentSearch(originalLoc,q);
  if(planningRequest){
    earthlineActivateSelectSiteMode("City planning view ready — click the area you want to evaluate. Earthline will zoom in and run site analysis automatically.");
    toast("Click anywhere on the map to select and analyze a 20-acre site.");
  }
  return true;
}

