function earthlineHistoryNormalize15774(value){
  return String(value||"").trim().toLowerCase().replace(/\s+/g," ");
}
function earthlineHistoryEscape15774(value){
  return String(value||"")
    .replace(/&/g,"&amp;")
    .replace(/"/g,"&quot;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;");
}
function earthlineLoadSearchHistory15774(){
  let saved=[];
  try{
    const raw=localStorage.getItem(EARTHLINE_SEARCH_HISTORY_KEY_15774);
    const parsed=raw?JSON.parse(raw):[];
    if(Array.isArray(parsed))saved=parsed;
  }catch(e){
    console.warn("[Earthline] Search history storage unavailable.",e);
  }

  const merged=[...saved,...EARTHLINE_KNOWN_PRIOR_SEARCHES_15774];
  const seen=new Set();
  RECENTS=[];
  for(const item of merged){
    const query=String(item&&item.query||item&&item.label||"").trim();
    const label=String(item&&item.label||query).trim();
    const key=earthlineHistoryNormalize15774(query||label);
    if(!key||seen.has(key))continue;
    seen.add(key);
    RECENTS.push({
      query:query||label,
      label:label||query,
      at:Number(item&&item.at||0)
    });
  }
  RECENTS.sort((a,b)=>Number(b.at||0)-Number(a.at||0));
  RECENTS=RECENTS.slice(0,EARTHLINE_SEARCH_HISTORY_LIMIT_15774);
}
function earthlineSaveSearchHistory15774(){
  try{
    localStorage.setItem(
      EARTHLINE_SEARCH_HISTORY_KEY_15774,
      JSON.stringify(RECENTS.slice(0,EARTHLINE_SEARCH_HISTORY_LIMIT_15774))
    );
  }catch(e){
    console.warn("[Earthline] Could not save search history.",e);
  }
}
function addRecentSearch(loc,queryText=""){
  const label=loc&&(
    loc.fullName||
    ((loc.name||"")+(loc.sub?", "+loc.sub:""))
  );
  const query=String(queryText||label||"").trim();
  if(!query&&!label)return;

  const key=earthlineHistoryNormalize15774(query||label);
  RECENTS=RECENTS.filter(item=>
    earthlineHistoryNormalize15774(item.query||item.label)!==key
  );
  RECENTS.unshift({
    query:query||label,
    label:String(label||query),
    at:Date.now()
  });
  RECENTS=RECENTS.slice(0,EARTHLINE_SEARCH_HISTORY_LIMIT_15774);
  earthlineSaveSearchHistory15774();
  rebuildLocList();
}
function rebuildLocList(){
  const recent=RECENTS.map(item=>{
    const query=earthlineHistoryEscape15774(item.query||item.label);
    const label=earthlineHistoryEscape15774(item.label||item.query);
    return '<option value="'+query+'" label="Recent · '+label+'"></option>';
  }).join("");
  const cityPresets='<option value="Glenwood Springs, CO" label="City / valley planning view"></option>';
  const presets=GAZ.map(g=>
    '<option value="'+earthlineHistoryEscape15774(g.name+', '+g.sub)+'"></option>'
  ).join("");
  const list=document.getElementById("locList");
  if(list)list.innerHTML=recent+cityPresets+presets;
}
