/* ---------------- RNG + noise ---------------- */
function hashStr(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function latHash(ix,iy,seed){let n=ix*374761393+iy*668265263+seed*1442695041;n=(n^(n>>13))*1274126177;n=n^(n>>16);return(n>>>0)/4294967296;}
function smoothT(t){return t*t*(3-2*t);}
function vnoise(x,y,seed){
  const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;
  const a=latHash(ix,iy,seed),b=latHash(ix+1,iy,seed),c=latHash(ix,iy+1,seed),d=latHash(ix+1,iy+1,seed);
  const u=smoothT(fx),v=smoothT(fy);
  return a*(1-u)*(1-v)+b*u*(1-v)+c*(1-u)*v+d*u*v;
}
function fbm(x,y,seed,oct){let v=0,amp=0.5,f=1;for(let i=0;i<oct;i++){v+=amp*vnoise(x*f,y*f,seed+i*101);f*=2;amp*=0.5;}return v;}
