async function geocodeMapbox(q,myGen=M.searchGen){
  const exactRegion=earthlineRegionOverride(q);
  if(exactRegion)return exactRegion;
  const url="https://api.mapbox.com/geocoding/v5/mapbox.places/"+encodeURIComponent(earthlinePlaceLookupQuery16541(q))+".json?limit=10&language=en&access_token="+MAPBOX_TOKEN;
  const r=await fetch(url);
  if(earthlineIsStale(myGen))return null;
  if(!r.ok)throw new Error("geocode failed");
  const j=await r.json();
  if(earthlineIsStale(myGen))return null;
  if(!j.features||!j.features.length)return null;
  const f=earthlineSelectPlaceCandidate16537(q,j.features);
  if(!f)return null;
  const zh=PLACE_ZOOM[(f.place_type&&f.place_type[0])||"place"]||15;
  // For large areas (states, countries, regions) Mapbox returns a bbox [W,S,E,N].
  // Derive a zoom that fits the whole area to the map window so e.g. "Colorado" frames
  // the entire state rather than centering mid-state at a fixed zoom.
  let fitZoom=zh, bbox=f.bbox||null;
  if(bbox){
    const wKm=Math.abs(bbox[2]-bbox[0])*111*Math.cos(f.center[1]*Math.PI/180);
    const hKm=Math.abs(bbox[3]-bbox[1])*111;
    const spanKm=Math.max(wKm,hKm*GW/GH);   // largest dimension the window must cover
    // window must be ~spanKm wide: window = GW * cellM, cellM = 5 * mppAt(z).
    // NOTE: mppAt(z,lat) = 156573.03 * cos(lat) / 2^z / 2  (note the trailing /2),
    // so solve 156573.03*cos/2^(z+1) = targetMpp  ->  z = log2(156573*cos/(2*targetMpp)).
    const targetMpp=(spanKm*1000*2.10)/(GW*5);   // 14300: full state plus surrounding-state edges, faster state framing
    const c=Math.cos(f.center[1]*Math.PI/180);
    fitZoom=clamp(Math.log2(156573.03*c/(2*Math.max(targetMpp,0.01))),3,18);
  }
  const countryFeature=((f.place_type||[]).includes("country")?f:(f.context||[]).find(c=>String(c.id||"").startsWith("country.")))||null;
  const countryCode=String(countryFeature&&((countryFeature.properties&&countryFeature.properties.short_code)||countryFeature.short_code)||"").toLowerCase().slice(0,2);
  return {
    q:q.toLowerCase(),
    name:f.text||f.place_name.split(",")[0],
    sub:f.place_name.split(",").slice(1).join(",").trim()||"Geocoded location",
    fullName:f.place_name,countryCode,
    lat:f.center[1],lng:f.center[0],zoomHint:fitZoom,bbox:bbox,
    placeType:((f.place_type&&f.place_type[0])||"place"),
    acres:20,elevM:0,precipIn:30,trendDeg:180,trendSlope:6,relief:8,rough:1,runC:0.35,
    zones:["Full View","East Offset","South Offset","West Offset"]
